package com.vms.vendorcontractmanagement.config; import io.jsonwebtoken.*; import io.jsonwebtoken.security.*; import org.springframework.beans.factory.annotation.*; import org.springframework.stereotype.*; import java.nio.charset.*; import java.util.*; import javax.crypto.*;
@Service public class JwtService { @Value("${app.jwt.secret}") String secret; @Value("${app.jwt.expiration-ms}") long expiration; private SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String generate(String email,String role){return Jwts.builder().subject(email).claim("role",role).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration)).signWith(key()).compact();} public Claims claims(String token){return Jwts.parser().verifyWith(key()).build().parseSignedClaims(token).getPayload();} }
